import json, re, unicodedata, html
from pathlib import Path

ROOT=Path(__file__).parent
OUT=ROOT/'dist'
OUT.mkdir(exist_ok=True)
titles=['Arthur Rimbaud','Victor Hugo','La Comtesse de Ségur','Marcel Proust','George Sand','Jules Verne','Émile Zola','Honoré de Balzac','Colette','Collector n° 1','Molière','Charles Baudelaire','Paul Verlaine','Alexandre Dumas','Pierre Corneille','Jean Racine','Jean de La Fontaine','Guy de Maupassant','Alphonse Daudet','Collector n° 2','Gustave Flaubert','François-René de Chateaubriand','Georges Courteline','Prosper Mérimée','Charles Perrault','Mme de Sévigné','Mme de la Fayette','Edmond Rostand','Joachim du Bellay','Collector n° 3','François Rabelais','Sophocle','Aristophane']
isbns=['9782952781749','9782952781756','9782952781763','9782952781770','9782952781787','9782952781794','9782489192001','9782489192018','9782489192025','9782489192056','9782489192032']
colors=['#b96c91','#e6a34e','#ae76ae','#77a7a2','#7f9d68','#789eb7','#c27b72','#b28f60','#a494b8','#e9a048','#9bb297']
def slug(t): return re.sub(r'[^a-z0-9]+','-',unicodedata.normalize('NFKD',t).encode('ascii','ignore').decode().lower()).strip('-')
books=[dict(number=i,title=t,slug=slug(t),available=i<=11 and i!=10,price=9 if i<3 else 18 if i==10 else 15,pages=16 if i<3 else 32 if i in [10,20,30] else 24,isbn=isbns[i-1] if i<=11 else '',color=colors[(i-1)%len(colors)],cover='',description='') for i,t in enumerate(titles,1)]
if (ROOT/'content.json').exists():
    books=json.loads((ROOT/'content.json').read_text())['books']
else:(ROOT/'content.json').write_text(json.dumps({'books':books,'events':[]},ensure_ascii=False,indent=2))
def esc(t):return html.escape(str(t),quote=True)
def cover(b,hero=False):
    if b.get('cover'): return f'<img class="real-cover" src="{esc(b["cover"])}" alt="Couverture de {esc(b["title"])}">'
    return f'<div class="book-cover {"big" if hero else ""}" style="--book:{b["color"]}"><span class="series">Les plus grands racontés<br>aux plus petits</span><div class="cover-art"><span class="orbit">✳</span><span class="initial">{esc(b["title"].split()[-1][0])}</span></div><strong>{esc(b["title"])}</strong><span class="cover-bottom">N° {b["number"]:02} · Visuel provisoire</span></div>'
def cards(items):return ''.join(f'<a class="book-card" href="/livres/{b["slug"]}/">{cover(b)}<div class="card-meta"><span>N° {b["number"]:02}</span><span>{str(b["price"])+" €" if b["available"] else "À paraître"}</span></div><h3>{esc(b["title"])}</h3></a>' for b in items)
def link(text,url,kind='primary'):return f'<a class="button {kind}" href="{url}">{text} <span aria-hidden="true">↗</span></a>'
def heading(kicker,title,text=''):return f'<div class="page-heading"><p class="eyebrow">{kicker}</p><h1>{title}</h1>{"<p class=lead>"+text+"</p>" if text else ""}</div>'
SUMUP='https://sur-le-chemin-des-arts.sumupstore.com/'
def page(path,title,body,description='',active='',extra=''):
    p=OUT/path.strip('/')/'index.html';p.parent.mkdir(parents=True,exist_ok=True)
    nav=''.join(f'<a {"aria-current=page" if active==name else ""} href="{url}">{name}</a>' for name,url in [('La collection','/livres/'),('Les autrices','/autrices/'),('Où nous trouver','/agenda/'),('Professionnels','/professionnels/')])
    p.write_text(f'''<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(title)} · Les plus grands racontés</title><meta name="description" content="{esc(description or 'Des livres pour découvrir les grands auteurs dès 5 ans. Une collection illustrée, culturelle et ludique.')}"><meta name="robots" content="noindex,nofollow"><meta name="theme-color" content="#6d3d72"><meta property="og:title" content="{esc(title)}"><meta property="og:description" content="Une première rencontre avec les grands auteurs, dès 5 ans."><link rel="stylesheet" href="/style.css">{extra}</head><body><a class="skip" href="#main">Aller au contenu</a><div class="topline">Une petite bibliothèque. De grandes découvertes. <span>Dès 5 ans · Jusqu’à 10 ans</span></div><header><a class="brand" href="/" aria-label="Accueil"><span class="brand-mark">✳</span><span>Les plus grands<br><em>racontés aux plus petits</em></span></a><button class="menu-toggle" aria-expanded="false" aria-controls="nav">Menu ☰</button><nav id="nav">{nav}<a class="nav-order" href="{SUMUP}" target="_blank" rel="noopener">Commander ↗</a></nav></header><main id="main">{body}</main><section class="footer-banner"><span class="little-star">✳</span><div><p class="eyebrow">À lire, à partager, à garder</p><h2>Le début d’une grande histoire<br>avec les livres.</h2></div>{link('Explorer la collection','/livres/')}</section><footer><div class="footer-top"><a class="brand" href="/">Les plus grands<br><em>racontés aux plus petits</em></a><p>Une collection de Sur le Chemin des Arts.<br>Imaginée par Hervélina Vyskoc et Valérie Lemoine.</p><div><a href="/offrir/">Offrir & s’abonner</a><a href="/bonus/">Bonus & activités</a><a href="/presse/">Presse</a><a href="/contact/">Contact</a></div></div><div class="footer-bottom"><span>© 2026 Sur le Chemin des Arts · V1.0.0</span><div><a href="/mentions-legales/">Mentions légales</a><a href="/cgv/">CGV</a><a href="/confidentialite/">Confidentialité</a><a href="/atelier/">Atelier de contenu</a></div></div></footer><script src="/app.js" defer></script></body></html>''',encoding='utf-8')

hero_books=''.join(f'<div class="hero-book hb{i}">{cover(books[n],True)}</div>' for i,n in enumerate([1,5,8]))
home=f'''<section class="hero"><div class="hero-copy"><p class="eyebrow"><span class="dot"></span> La curiosité n’a pas d’âge</p><h1>Petits lecteurs,<br><em>grandes</em><br>découvertes<span class="pink-dot">.</span></h1><p class="lead">Rimbaud, Hugo, Colette… Et si leur histoire commençait dans les petites mains de vos enfants ?</p><p>Des livres illustrés pour rencontrer les grands auteurs,<br class="desktop"> apprendre en s’amusant et lire ensemble, de 5 à 10 ans.</p><div class="actions">{link('Découvrir les livres','/livres/')}{link('Un cadeau qui grandit','/offrir/','text')}</div><div class="hero-note"><span>✧</span> Lecture accompagnée dès 5 ans.<br>Des découvertes à partager à tout âge.</div></div><div class="hero-visual"><div class="sunburst"></div><span class="scribble">De grands noms,<br>de belles rencontres.</span>{hero_books}<span class="visual-note">Les couvertures arrivent bientôt</span><span class="age-seal">5–10<span>ans</span></span></div></section><div class="promise-strip"><span>✳ Imaginé par deux autrices</span><span>✳ Imprimé en France</span><span>✳ Petits formats, grands horizons</span></div><section class="section"><div class="section-heading"><div><p class="eyebrow">Une bibliothèque qui prend vie</p><h2>Lequel rencontrerez-vous<br>en premier ?</h2></div><a class="underlink" href="/livres/">Les 10 livres disponibles →</a></div><div class="book-grid featured">{cards([books[i] for i in [0,1,5,8]])}</div></section><section class="discovery section"><div class="discovery-art"><div class="spread"><div><span>Il était une fois…</span><div class="flower">✳</div><p>Un auteur,<br>mille idées.</p></div><div><span>Et si on jouait ?</span><div class="writing-lines"></div><p>Votre extrait<br>prendra place ici.</p></div></div><small>Aperçu intérieur provisoire</small></div><div><p class="eyebrow">Bien plus qu’une histoire</p><h2>On ouvre un livre.<br>On ouvre un monde.</h2><p>La vie d’un auteur, un extrait de son œuvre, des échappées culturelles et des activités : chaque livre donne envie de poursuivre la découverte.</p><ul class="feature-list"><li><span>01</span> Découvrir une vie et une œuvre</li><li><span>02</span> Lire, observer, s’émerveiller</li><li><span>03</span> Explorer d’autres horizons</li><li><span>04</span> Jouer et créer à son tour</li></ul></div></section><section class="gift-band section"><p class="eyebrow">Pour les petits curieux de votre vie</p><h2>Un cadeau qui ne s’arrête<br>pas à la dernière page.</h2><p>Un livre, plusieurs découvertes. Ou une bibliothèque à construire au fil des parutions.</p>{link('Les idées cadeaux & abonnements','/offrir/')}</section><section class="section authors-intro"><div class="photo-placeholder"><span>✳</span><p>Hervélina & Valérie</p><small>Votre photo prendra place ici</small></div><div><p class="eyebrow">Les autrices</p><h2>Deux regards.<br>Une même envie de transmettre.</h2><p>Hervélina Vyskoc, comédienne et écrivain, et Valérie Lemoine, enseignante, ont réuni leur sensibilité et leur expérience pour éveiller la curiosité des enfants.</p>{link('L’histoire de la collection','/autrices/','text')}</div></section><section class="section pro-band"><div><p class="eyebrow">Librairies · Écoles · Bibliothèques · Musées</p><h2>Faisons grandir<br>la curiosité ensemble.</h2></div><div><p>Vous souhaitez accueillir la collection, recevoir un devis ou nous inviter à un salon ?</p>{link('L’espace professionnels','/professionnels/','light')}</div></section>'''
home += '<section class="section home-press"><div class="section-heading"><div><p class="eyebrow">Ils parlent de nous</p><h2>La collection fait<br>parler d’elle.</h2></div><a class="underlink" href="/presse/">Toute la revue de presse →</a></div><p>Découvrez les articles consacrés à la collection et aux autrices.</p><div class="press-names"><a href="/presse/">Actu.fr <span>↗</span></a><a href="/presse/">Ouest-France <span>↗</span></a><a href="/presse/">Le Flâneur <span>↗</span></a><a href="/presse/">La République<br>des Pyrénées <span>↗</span></a></div></section>'
page('','Les grands auteurs à découvrir dès 5 ans',home)
catalog=heading('La collection','À chacun sa première<br><em>grande rencontre.</em>','Dix livres à découvrir aujourd’hui. Une collection de 33 numéros pour accompagner la curiosité de vos enfants.')+'''<section class="section catalog-section"><div class="filter-bar" role="group" aria-label="Filtrer les livres"><button class="filter active" data-filter="available" aria-pressed="true">Disponibles · 10</button><button class="filter" data-filter="future" aria-pressed="false">À paraître · 23</button><button class="filter" data-filter="all" aria-pressed="false">Toute la collection · 33</button><label class="search-label">Chercher un auteur <input id="book-search" type="search" placeholder="Hugo, Colette…"></label></div><p class="muted">Les prochaines parutions sont présentées à titre de programme, sans date de sortie annoncée. Visuels provisoires.</p><div class="book-grid catalog">'''+''.join(f'<div data-book data-status="{"available" if b["available"] else "future"}" data-title="{esc(b["title"])}" {"hidden" if not b["available"] else ""}>{cards([b])}</div>' for b in books)+'''</div><p id="empty-results" hidden>Aucun auteur ne correspond à votre recherche.</p></section>'''
page('livres','Toute la collection',catalog,active='La collection')
for b in books:
    available=b['available']; collector=b['number'] in [10,20,30]
    price=f'{b["price"]} €' if available else '18 € · prix envisagé' if b['number']==10 else 'À paraître'
    content=f'''<section class="section product"><div><a class="backlink" href="/livres/">← Toute la collection</a><div class="product-visual">{cover(b,True)}</div></div><div class="product-copy"><p class="eyebrow">N° {b['number']:02} · {"Disponible" if available else "À paraître"}</p><h1>{esc(b['title'])}</h1><p class="lead">{ 'Des jeux et des activités pour prolonger les découvertes de la collection.' if collector else 'Une première rencontre avec '+esc(b['title'])+', pour les enfants de 5 à 10 ans.'}</p><p>{esc(b.get('description') or 'La présentation détaillée de ce livre sera ajoutée prochainement : son histoire, l’extrait choisi et les activités à découvrir.')}</p><div class="product-price">{price}</div>{link('Commander dans la boutique SumUp',SUMUP) if available else '<p class="notice">Ce numéro est en préparation. Il n’est pas encore proposé à la vente.</p>'}<p class="muted">{ 'Le choix des quantités et le paiement se font dans SumUp. Frais de livraison en supplément.' if available else 'La date de parution sera précisée prochainement.'}</p><dl class="specs"><div><dt>Âge</dt><dd>5–10 ans</dd></div><div><dt>Format</dt><dd>18 × 18 cm</dd></div><div><dt>Pages</dt><dd>{b['pages'] if available or b['number']==10 else 'À confirmer'}</dd></div><div><dt>ISBN</dt><dd>{b['isbn'] or 'À renseigner'}</dd></div></dl><p class="muted">Hervélina Vyskoc & Valérie Lemoine<br>Illustrations : John · Sur le Chemin des Arts</p>{'<a class="underlink" href="/bonus/moliere/">Écouter le bonus de Molière →</a>' if b['number']==11 else ''}</div></section><section class="section"><p class="eyebrow">Un petit aperçu</p><h2>À l’intérieur du livre</h2><div class="excerpt-grid">{''.join('<div class="excerpt-placeholder"><span>0'+str(i)+'</span><h3>'+s+'</h3><p>Extrait à ajouter</p></div>' for i,s in enumerate(['La vie de l’auteur','Un extrait à découvrir','Une échappée culturelle','À vous de jouer'],1))}</div></section><section class="section"><div class="section-heading"><h2>La découverte continue…</h2><a class="underlink" href="/livres/">Tous les livres →</a></div><div class="book-grid featured">{cards([x for x in books if x['available'] and x!=b][:4])}</div></section>'''
    page('livres/'+b['slug'],b['title']+' raconté aux enfants',content,active='La collection')
offers=[('Duo','Deux titres à 15 € au choix','30 € de livres + 7 € de port','37 €'),('Trio','Trois titres à 15 € au choix','45 € de livres + 7 € de port','52 €'),('Les quatre premiers','Rimbaud, Hugo, Ségur et Proust','48 € de livres + 9 € de port','57 €'),('La collection parue','Les dix titres disponibles','138 € de livres + 11 € de port','149 €')]
offerbody=heading('Offrir & s’abonner','De belles histoires<br><em>à faire grandir.</em>','Pour un anniversaire, pour Noël ou simplement pour le plaisir de découvrir.')+'<section class="section"><h2>Une petite bibliothèque en cadeau</h2><p>Prix des commandes groupées, livraison en France comprise. Le choix et le paiement se font dans la boutique.</p><div class="offer-grid">'+''.join(f'<article class="offer"><p class="eyebrow">{n}</p><h3>{d}</h3><strong class="offer-price">{p}</strong><p>{detail}</p>{link("Choisir dans la boutique",SUMUP,"text")}</article>' for n,d,detail,p in offers)+'</div><p class="notice">Les options de dédicace et d’emballage cadeau sont en cours de définition. Elles ne sont pas encore garanties.</p></section><section class="section subscription"><p class="eyebrow">Le plaisir des prochaines parutions</p><h2>Six nouvelles rencontres.<br>Une collection qui grandit.</h2><p>Les prochains titres de 24 pages, du n° 12 au n° 17 : Baudelaire, Verlaine, Dumas, Corneille, Racine et La Fontaine.</p><div class="subscription-options"><article><h3>Au rythme des parutions</h3><strong class="offer-price">120 €</strong><p>90 € de livres + 30 € de port et d’emballage.<br>Six envois, un par parution.</p></article><article><h3>En deux rendez-vous</h3><strong class="offer-price">104 €</strong><p>90 € de livres + 14 € de port.<br>Deux envois de trois livres.</p></article></div><p>Formules envisagées pour la France, payées en une fois. Le calendrier et les conditions de souscription restent à préciser.</p>'+link('Me renseigner sur l’abonnement','/contact/?sujet=abonnement')+'</section>'
page('offrir','Offrir des livres & abonnement',offerbody)
page('autrices','Hervélina Vyskoc & Valérie Lemoine',heading('Notre histoire','Une envie commune :<br><em>transmettre la curiosité.</em>')+'''<section class="section authors-intro"><div class="photo-placeholder"><span>✳</span><p>Hervélina & Valérie</p><small>Photo des autrices à ajouter</small></div><div><h2>Tout commence par un constat.</h2><p>Au fil de ses expériences auprès de publics variés, Hervélina Vyskoc a constaté que de grands auteurs étaient parfois peu connus. Elle a eu envie de proposer aux plus petits une première rencontre avec ces figures de la culture.</p><p>Avec Valérie Lemoine, enseignante, elle a imaginé une collection qui conjugue découverte, lecture et jeu. Des ouvrages qui éveillent l’envie d’en savoir plus et permettent à chaque enfant de construire sa bibliothèque personnelle.</p></div></section><section class="section two-columns"><article><p class="eyebrow">La sensibilité artistique</p><h2>Hervélina Vyskoc</h2><p>Comédienne et écrivain, Hervélina aime lire, écrire, peindre et écouter de la musique. À l’initiative de la collection, elle souhaite partager son attachement aux grands artistes et donner aux enfants l’envie de les découvrir.</p></article><article><p class="eyebrow">L’expérience pédagogique</p><h2>Valérie Lemoine</h2><p>Enseignante d’allemand auprès des enfants, Valérie vit aujourd’hui en Bretagne. Passionnée de lecture, de nature et de jardinage, elle apporte son expérience et son sens de l’organisation à cette aventure commune.</p></article></section>''',active='Les autrices')
form='''<form id="contact-form" class="contact-form"><label>Vous êtes<select name="profil"><option>Un particulier</option><option>Une librairie</option><option>Une bibliothèque ou médiathèque</option><option>Un musée ou une maison d’écrivain</option><option>Une école ou Alliance française</option><option>Un organisateur de salon</option><option>Un journaliste</option><option>Autre</option></select></label><label>Nom / structure<input name="nom" required autocomplete="name"></label><label>Votre e-mail<input name="email" type="email" required autocomplete="email"></label><label>Sujet<input name="sujet" required></label><label class="full">Votre message<textarea name="message" rows="5" required></textarea></label><p class="notice full">Formulaire de préparation : l’envoi sera activé après la création de l’adresse de contact. Aucun message n’est transmis pour le moment.</p><button class="button primary" type="submit">Préparer mon message ↗</button><div id="message-result" class="full" role="status"></div></form>'''
page('professionnels','Libraires, écoles, bibliothèques et musées',heading('Travaillons ensemble','De grandes découvertes<br><em>à partager.</em>','Librairies, bibliothèques, musées, écoles et salons : vous échangez directement avec les autrices.')+'''<section class="section two-columns"><article><h2>Accueillir la collection</h2><p>Découvrez les dix titres disponibles, leurs ISBN et leurs prix sur les fiches livres. La collection est référencée sur Dilicom via CyberScribe ; les commandes directes sont également possibles.</p><p>Les conditions professionnelles et documents de commande seront ajoutés après validation par les autrices.</p></article><article><h2>Construire un projet</h2><p>Un devis pour une bibliothèque, un titre pour la boutique d’un musée, une invitation à un salon ? Présentez-nous votre structure et votre projet.</p><p>Pour plus de douze livres, contactez-nous pour une proposition adaptée.</p></article></section><section class="section form-section"><h2>Parlons de votre projet</h2>'''+form+'</section>',active='Professionnels')
page('contact','Contact',heading('Écrivez-nous','Une question ?<br><em>Une idée à partager ?</em>','Collection, commande spéciale, abonnement ou collaboration : préparons votre demande.')+'<section class="section form-section">'+form+'</section>')
page('agenda','Où nous trouver',heading('Rencontrons-nous','Des livres, des lieux,<br><em>des rencontres.</em>','Retrouvez les prochaines dates de salons et de dédicaces, ainsi que les points de vente de la collection.')+'''<section class="section"><div class="empty-panel"><span>✳</span><h2>L’agenda se prépare</h2><p>Les lieux, dates et horaires seront ajoutés ici au fil des confirmations.</p><a class="underlink" href="/contact/">Nous inviter à un événement →</a></div><h2>Chez votre libraire aussi</h2><p>Vous pouvez demander la collection à votre libraire, avec le titre ou l’ISBN du livre. Les adresses des points de vente partenaires seront ajoutées prochainement.</p></section>''',active='Où nous trouver')
page('bonus','Bonus & activités',heading('La découverte continue','Des pages aux oreilles,<br><em>et au bout des doigts.</em>','Retrouvez ici les prolongements des livres de la collection.')+'<section class="section"><article class="bonus-card"><span class="sound-icon">♫</span><div><p class="eyebrow">Tome 11 · Molière</p><h2>Le théâtre s’écoute aussi</h2><p>Une lecture sous forme d’interprétation théâtrale, pour prolonger la découverte.</p>'+link('Découvrir le bonus','/bonus/moliere/','text')+'</div></article></section>')
page('bonus/moliere','Le bonus audio de Molière',heading('Tome 11 · Bonus audio','Place au théâtre !','Le prolongement sonore du livre consacré à Molière.')+'<section class="section"><div class="empty-panel"><span>♫</span><h2>Le fichier audio arrive bientôt</h2><p>Le lecteur sera installé ici dès réception de l’enregistrement.</p></div><p class="notice">Le QR code déjà imprimé conserve son adresse actuelle. Son acheminement vers cette page sera configuré lors de la mise en ligne définitive.</p></section>')
