for path,title,txt in [('mentions-legales','Mentions légales','Éditeur : Sur le Chemin des Arts. Les informations d’identité, le statut exact, le SIRET, l’adresse, la direction de publication et l’hébergement définitif restent à compléter.'),('cgv','Conditions générales de vente','Les conditions définitives seront ajoutées avant l’ouverture commerciale : livraison, retours, rétractation, médiation et conditions de l’abonnement. Les commandes et paiements sont effectués dans la boutique SumUp, dont les conditions doivent être consultées avant achat.'),('confidentialite','Confidentialité','Les formulaires de cette version de travail ne transmettent aucune donnée. Aucun outil de mesure d’audience ni inscription à une newsletter n’est activé. L’atelier de contenu enregistre les modifications uniquement dans le navigateur utilisé. La politique définitive sera adaptée aux services réellement activés.')]:
    page(path,title,heading('Version de travail',title)+f'<section class="section prose"><p class="notice">Page à finaliser avant publication publique.</p><p>{txt}</p></section>')
page('atelier','Atelier de contenu',heading('Préparation des contenus','Votre atelier<br><em>pour faire évoluer le site.</em>','Préparez les textes et les couvertures à votre rythme.')+'''<section class="section form-section"><p class="notice">Prototype local, sans connexion administrateur : les modifications sont conservées dans ce navigateur et prévisualisées ici. Elles ne modifient pas le site publié. Exportez le fichier pour conserver et intégrer vos contenus. Une administration sécurisée sera raccordée dans une prochaine étape.</p><div class="editor-grid"><form id="editor"><label>Livre<select id="editor-book"></select></label><label>Description<textarea id="editor-description" rows="6"></textarea></label><label>Adresse de la couverture<input id="editor-cover" type="url" placeholder="https://…"></label><label>Ou sélectionner une image<input id="editor-file" type="file" accept="image/png,image/jpeg,image/webp"></label><button class="button primary" type="submit">Enregistrer dans ce navigateur</button><p id="editor-status" role="status"></p></form><div id="editor-preview"></div></div><div class="actions"><button id="export-content" class="button primary">Exporter les contenus JSON ↓</button><label class="button light">Importer un fichier JSON<input id="import-content" type="file" accept="application/json" hidden></label></div><p id="import-status" role="status"></p></section>''')
(OUT/'content.json').write_text((ROOT/'content.json').read_text())
(OUT/'robots.txt').write_text('User-agent: *\nDisallow: /\n')
(ROOT/'README.md').write_text('''# Les plus grands racontés aux plus petits — V0.1\n\nSite statique de travail, sans dépendance.\n\nConstruction : `python3 build.py`\nDossier publié : `dist/`\nVercel : commande de build `python3 build.py`, sortie `dist`.\n\nLe catalogue est dans `content.json`. Remplacer les couvertures via le champ `cover` et les descriptions via `description`. Déposer les images dans `dist/assets/` ou utiliser une URL HTTPS. Le script conserve les fichiers présents dans dist.\n\nL’atelier est un prototype local avec import/export JSON. Il n’est pas une administration authentifiée et ne publie pas ses modifications. Remplacer content.json par le fichier exporté, puis reconstruire pour intégrer les changements.\n\nAvant ouverture : réception des images et extraits, liens SumUp par produit et formules, confirmation prix Collector, conditions abonnement/cadeaux, adresse email et formulaire serveur, administration sécurisée, mentions légales/CGV, redirection QR existante, audio Molière, domaine et suppression noindex/robots Disallow. Ajouter canonical, sitemap et données structurées sur le domaine définitif, à partir des disponibilités et offres vérifiées.\n\nAucune photo ni citation d’Amélie Nothomb n’est publiée dans cette version.\n''')
print(f'{len(list(OUT.rglob("index.html")))} pages générées')
